const S390_LPP_PID_MASK: u64 = 0xffffffff;

#[repr(C)]
struct s390_cpumsf {
    auxtrace: auxtrace,
    queues: auxtrace_queues,
    heap: auxtrace_heap,
    session: *mut perf_session,
    machine: *mut machine,
    auxtrace_type: u32,
    pmu_type: u32,
    machine_type: u16,
    data_queued: bool,
    use_logfile: bool,
    logdir: *mut c_char,
}

#[repr(C)]
struct s390_cpumsf_queue {
    sf: *mut s390_cpumsf,
    queue_nr: c_uint,
    buffer: *mut auxtrace_buffer,
    cpu: c_int,
    logfile: *mut FILE,
    logfile_ctr: *mut FILE,
}

