unsafe fn be16toh(x: u16) -> u16 { u16::from_be(x) }
unsafe fn be64toh(x: u64) -> u64 { u64::from_be(x) }

/* Check if the raw data should be dumped to file. If this is the case and
 * the file to dump to has not been opened for writing, do so.
 *
 * Return 0 on success and greater zero on error so processing continues.
 */
unsafe extern "C" fn s390_cpumcf_dumpctr(sf: *mut s390_cpumsf, sample: *mut perf_sample) -> c_int {
    let mut rc: c_int = 0;

    if !(*sf).use_logfile || (*sf).queues.nr_queues <= (*sample).cpu as c_uint {
        return rc;
    }

    let q = (*sf).queues.queue_array.add((*sample).cpu as usize);
    let sfq = (*q).priv_ as *mut s390_cpumsf_queue;
    if sfq.is_null() {
        return rc;
    }

    if (*sfq).logfile_ctr.is_null() {
        let mut name: *mut c_char = null_mut();

        rc = if !(*sf).logdir.is_null() {
            asprintf(&mut name, b"%s/aux.ctr.%02x\0".as_ptr() as *const c_char, (*sf).logdir, (*sample).cpu)
        } else {
            asprintf(&mut name, b"aux.ctr.%02x\0".as_ptr() as *const c_char, (*sample).cpu)
        };
        if rc > 0 {
            (*sfq).logfile_ctr = fopen(name, b"w\0".as_ptr() as *const c_char);
        }
        if (*sfq).logfile_ctr.is_null() {
            pr_err(b"Failed to open counter set log file %s, continue...\n\0".as_ptr() as *const c_char, name);
            rc = 1;
        }
        free(name as *mut c_void);
    }

    if !(*sfq).logfile_ctr.is_null() {
        /* See comment above for -4 */
        let n = fwrite((*sample).raw_data, (*sample).raw_size.wrapping_sub(4), 1, (*sfq).logfile_ctr);
        if n != 1 {
            pr_err(b"Failed to write counter set data\n\0".as_ptr() as *const c_char);
            rc = 1;
        }
    }
    rc
}

/* Display s390 CPU measurement facility basic-sampling data entry
 * Data written on s390 in big endian byte order and contains bit
 * fields across byte boundaries.
 */
unsafe extern "C" fn s390_cpumsf_basic_show(color: *const c_char, pos: size_t, basicp: *mut hws_basic_entry) -> bool {
    let mut basic = basicp;
    #[cfg(target_endian = "little")]
    let mut local: hws_basic_entry = zeroed();
    #[cfg(target_endian = "little")]
    {
        let word = be64toh(*(basicp as *mut u64));

        memset(&mut local as *mut _ as *mut c_void, 0, size_of::<hws_basic_entry>());
        local.def = be16toh((*basicp).def);
        local.prim_asn = (word & 0xffff) as u16;
        local.CL = ((word >> 30) & 0x3) as u8;
        local.I = ((word >> 32) & 0x1) as u8;
        local.AS = ((word >> 33) & 0x3) as u8;
        local.P = ((word >> 35) & 0x1) as u8;
        local.W = ((word >> 36) & 0x1) as u8;
        local.T = ((word >> 37) & 0x1) as u8;
        local.U = ((word >> 40) & 0xf) as u8;
        local.ia = be64toh((*basicp).ia);
        local.gpp = be64toh((*basicp).gpp);
        local.hpp = be64toh((*basicp).hpp);
        basic = &mut local;
    }
    if (*basic).def != 1 {
        pr_err(b"Invalid AUX trace basic entry [%#08zx]\n\0".as_ptr() as *const c_char, pos);
        return false;
    }
    color_fprintf(stdout, color, b"    [%#08zx] Basic   Def:%04x Inst:%#04x %c%c%c%c AS:%d ASN:%#04x IA:%#018llx\n\t\tCL:%d HPP:%#018llx GPP:%#018llx\n\0".as_ptr() as *const c_char,
                  pos, (*basic).def as c_int, (*basic).U as c_int,
                  if (*basic).T != 0 { b'T' as c_int } else { b' ' as c_int },
                  if (*basic).W != 0 { b'W' as c_int } else { b' ' as c_int },
                  if (*basic).P != 0 { b'P' as c_int } else { b' ' as c_int },
                  if (*basic).I != 0 { b'I' as c_int } else { b' ' as c_int },
                  (*basic).AS as c_int, (*basic).prim_asn as c_int, (*basic).ia,
                  (*basic).CL as c_int, (*basic).hpp, (*basic).gpp);
    true
}

/* Display s390 CPU measurement facility diagnostic-sampling data entry.
 * Data written on s390 in big endian byte order and contains bit
 * fields across byte boundaries.
 */
unsafe extern "C" fn s390_cpumsf_diag_show(color: *const c_char, pos: size_t, diagp: *mut hws_diag_entry) -> bool {
    let mut diag = diagp;
    #[cfg(target_endian = "little")]
    let mut local: hws_diag_entry = zeroed();
    #[cfg(target_endian = "little")]
    {
        let word = be64toh(*(diagp as *mut u64));

        local.def = be16toh((*diagp).def);
        local.I = ((word >> 32) & 0x1) as u8;
        diag = &mut local;
    }
    if (*diag).def < S390_CPUMSF_DIAG_DEF_FIRST {
        pr_err(b"Invalid AUX trace diagnostic entry [%#08zx]\n\0".as_ptr() as *const c_char, pos);
        return false;
    }
    color_fprintf(stdout, color, b"    [%#08zx] Diag    Def:%04x %c\n\0".as_ptr() as *const c_char,
                  pos, (*diag).def as c_int, if (*diag).I != 0 { b'I' as c_int } else { b' ' as c_int });
    true
}

/* Return TOD timestamp contained in an trailer entry */
unsafe extern "C" fn trailer_timestamp(te: *mut hws_trailer_entry, idx: c_int) -> u64 {
    /* te->t set: TOD in STCKE format, bytes 8-15
     * to->t not set: TOD in STCK format, bytes 0-7
     */
    let mut ts: u64 = 0;

    memcpy(&mut ts as *mut _ as *mut c_void, (*te).timestamp.as_ptr().add(idx as usize) as *const c_void, size_of::<u64>());
    be64toh(ts)
}

/* Display s390 CPU measurement facility trailer entry */
unsafe extern "C" fn s390_cpumsf_trailer_show(color: *const c_char, pos: size_t, mut te: *mut hws_trailer_entry) -> bool {
    #[cfg(target_endian = "little")]
    let mut local: hws_trailer_entry = zeroed();
    #[cfg(target_endian = "little")]
    {
        let flags = be64toh((*te).flags);

        memset(&mut local as *mut _ as *mut c_void, 0, size_of::<hws_trailer_entry>());
        local.f = ((flags >> 63) & 0x1) as u8;
        local.a = ((flags >> 62) & 0x1) as u8;
        local.t = ((flags >> 61) & 0x1) as u8;
        local.bsdes = be16toh(((flags >> 16) & 0xffff) as u16);
        local.dsdes = be16toh((flags & 0xffff) as u16);
        memcpy(local.timestamp.as_mut_ptr() as *mut c_void, (*te).timestamp.as_ptr() as *const c_void, size_of::<[u8; 16]>());
        local.overflow = be64toh((*te).overflow);
        local.clock_base = ((be64toh((*te).progusage[0]) >> 63) & 1) != 0;
        local.progusage2 = be64toh((*te).progusage2);
        te = &mut local;
    }
    if (*te).bsdes as usize != size_of::<hws_basic_entry>() {
        pr_err(b"Invalid AUX trace trailer entry [%#08zx]\n\0".as_ptr() as *const c_char, pos);
        return false;
    }
    color_fprintf(stdout, color, b"    [%#08zx] Trailer %c%c%c bsdes:%d dsdes:%d Overflow:%lld Time:%#llx\n\t\tC:%d TOD:%#llx\n\0".as_ptr() as *const c_char,
                  pos,
                  if (*te).f != 0 { b'F' as c_int } else { b' ' as c_int },
                  if (*te).a != 0 { b'A' as c_int } else { b' ' as c_int },
                  if (*te).t != 0 { b'T' as c_int } else { b' ' as c_int },
                  (*te).bsdes as c_int, (*te).dsdes as c_int, (*te).overflow,
                  trailer_timestamp(te, (*te).clock_base as c_int),
                  (*te).clock_base as c_int, (*te).progusage2);
    true
}

/* Test a sample data block. It must be 4KB or a multiple thereof in size and
 * 4KB page aligned. Each sample data page has a trailer entry at the
 * end which contains the sample entry data sizes.
 *
 * Return true if the sample data block passes the checks and set the
 * basic set entry size and diagnostic set entry size.
 *
 * Return false on failure.
 *
 * Note: Old hardware does not set the basic or diagnostic entry sizes
 * in the trailer entry. Use the type number instead.
 */
unsafe extern "C" fn s390_cpumsf_validate(machine_type: c_int, buf: *mut u8, len: size_t, bsdes: *mut u16, dsdes: *mut u16) -> bool {
    let basic = buf as *mut hws_basic_entry;
    let te: *mut hws_trailer_entry;

    *dsdes = 0;
    *bsdes = *dsdes;
    if len & (S390_CPUMSF_PAGESZ - 1) != 0 {
        return false;
    }
    if be16toh((*basic).def) != 1 {
        return false;
    }
    te = buf.add(S390_CPUMSF_PAGESZ - size_of::<hws_trailer_entry>()) as *mut hws_trailer_entry;
    *bsdes = be16toh((*te).bsdes);
    *dsdes = be16toh((*te).dsdes);
    if (*te).bsdes == 0 && (*te).dsdes == 0 {
        match machine_type {
            2097 | 2098 => {
                *dsdes = 64;
                *bsdes = 32;
            }
            2817 | 2818 => {
                *dsdes = 74;
                *bsdes = 32;
            }
            2827 | 2828 => {
                *dsdes = 85;
                *bsdes = 32;
            }
            2964 | 2965 => {
                *dsdes = 112;
                *bsdes = 32;
            }
            _ => {
                /* Illegal trailer entry */
                return false;
            }
        }
    }
    true
}

/* Return true if there is room for another entry */
unsafe extern "C" fn s390_cpumsf_reached_trailer(entry_sz: size_t, pos: size_t) -> bool {
    let payload = S390_CPUMSF_PAGESZ - size_of::<hws_trailer_entry>();

    if payload - (pos & (S390_CPUMSF_PAGESZ - 1)) < entry_sz {
        return false;
    }
    true
}

/* Dump an auxiliary buffer. These buffers are multiple of
 * 4KB SDB pages.
 */
unsafe extern "C" fn s390_cpumsf_dump(sf: *mut s390_cpumsf, buf: *mut u8, len: size_t) {
    let color = PERF_COLOR_BLUE;
    let mut bsdes: u16 = 0;
    let mut dsdes: u16 = 0;
    let mut pos: size_t = 0;

    color_fprintf(stdout, color, b". ... s390 AUX data: size %zu bytes\n\0".as_ptr() as *const c_char, len);

    if !s390_cpumsf_validate((*sf).machine_type as c_int, buf, len, &mut bsdes, &mut dsdes) {
        pr_err(b"Invalid AUX trace data block size:%zu (type:%d bsdes:%hd dsdes:%hd)\n\0".as_ptr() as *const c_char,
               len, (*sf).machine_type as c_int, bsdes as c_int, dsdes as c_int);
        return;
    }

    /* s390 kernel always returns 4KB blocks fully occupied,
     * no partially filled SDBs.
     */
    while pos < len {
        let basic = buf.add(pos) as *mut hws_basic_entry;
        if s390_cpumsf_basic_show(color, pos, basic) {
            pos += bsdes as usize;
        } else {
            return;
        }

        let diag = buf.add(pos) as *mut hws_diag_entry;
        if s390_cpumsf_diag_show(color, pos, diag) {
            pos += dsdes as usize;
        } else {
            return;
        }

        if !s390_cpumsf_reached_trailer(bsdes as usize + dsdes as usize, pos) {
            let mut te: hws_trailer_entry = zeroed();

            pos = (pos + S390_CPUMSF_PAGESZ) & !(S390_CPUMSF_PAGESZ - 1);
            pos -= size_of::<hws_trailer_entry>();
            memcpy(&mut te as *mut _ as *mut c_void, buf.add(pos) as *const c_void, size_of::<hws_trailer_entry>());
            /* Set descriptor sizes in case of old hardware
             * where these values are not set.
             */
            te.bsdes = bsdes;
            te.dsdes = dsdes;
            if s390_cpumsf_trailer_show(color, pos, &mut te) {
                pos += size_of::<hws_trailer_entry>();
            } else {
                return;
            }
        }
    }
}

unsafe extern "C" fn s390_cpumsf_dump_event(sf: *mut s390_cpumsf, buf: *mut u8, len: size_t) {
    printf(b".\n\0".as_ptr() as *const c_char);
    s390_cpumsf_dump(sf, buf, len);
}

unsafe extern "C" fn s390_cpumsf_make_event(pos: size_t, basic: *mut hws_basic_entry, sfq: *mut s390_cpumsf_queue) -> bool {
    let mut sample: perf_sample = zeroed();
    let mut event: perf_event = zeroed();
    let ret: c_int;

    sample.ip = (*basic).ia;
    sample.pid = ((*basic).hpp & S390_LPP_PID_MASK) as pid_t;
    sample.tid = ((*basic).hpp & S390_LPP_PID_MASK) as pid_t;
    sample.cpumode = PERF_RECORD_MISC_CPUMODE_UNKNOWN;
    sample.cpu = (*sfq).cpu;
    sample.period = 1;

    if (*basic).CL == 1 {
        sample.cpumode = if (*basic).P != 0 { PERF_RECORD_MISC_USER } else { PERF_RECORD_MISC_KERNEL };
    } else if (*basic).CL == 2 {
        sample.cpumode = if (*basic).P != 0 { PERF_RECORD_MISC_GUEST_USER } else { PERF_RECORD_MISC_GUEST_KERNEL };
    } else if (*basic).gpp != 0 || (*basic).prim_asn != 0xffff {
        sample.cpumode = if (*basic).P != 0 { PERF_RECORD_MISC_GUEST_USER } else { PERF_RECORD_MISC_GUEST_KERNEL };
    } else {
        sample.cpumode = if (*basic).P != 0 { PERF_RECORD_MISC_USER } else { PERF_RECORD_MISC_KERNEL };
    }

    event.sample.header.type_ = PERF_RECORD_SAMPLE;
    event.sample.header.misc = sample.cpumode;
    event.sample.header.size = size_of::<perf_event_header>() as u16;

    pr_debug4(b"%s pos:%#zx ip:%#llx P:%d CL:%d pid:%d.%d cpumode:%d cpu:%d\n\0".as_ptr() as *const c_char,
              b"s390_cpumsf_make_event\0".as_ptr() as *const c_char, pos, sample.ip,
              (*basic).P as c_int, (*basic).CL as c_int, sample.pid, sample.tid,
              sample.cpumode as c_int, sample.cpu);
    ret = perf_session__deliver_synth_event((*(*sfq).sf).session, &mut event, &mut sample);
    perf_sample__exit(&mut sample);
    if ret != 0 {
        pr_err(b"s390 Auxiliary Trace: failed to deliver event\n\0".as_ptr() as *const c_char);
        return false;
    }
    true
}

unsafe extern "C" fn get_trailer_time(buf: *const u8) -> u64 {
    let te = buf.add(S390_CPUMSF_PAGESZ - size_of::<hws_trailer_entry>()) as *mut hws_trailer_entry;
    let aux_time: u64;
    let progusage2: u64;
    let clock_base: bool;

    #[cfg(target_endian = "little")]
    {
        clock_base = ((be64toh((*te).progusage[0]) >> 63) & 0x1) != 0;
        progusage2 = be64toh((*te).progusage[1]);
    }
    #[cfg(not(target_endian = "little"))]
    {
        clock_base = (*te).clock_base;
        progusage2 = (*te).progusage2;
    }
    if !clock_base {
        return 0;
    }

    /* Correct calculation to convert time stamp in trailer entry to
     * nano seconds (taken from arch/s390 function tod_to_ns()).
     * TOD_CLOCK_BASE is stored in trailer entry member progusage2.
     */
    let mut aux_time_mut = trailer_timestamp(te, clock_base as c_int).wrapping_sub(progusage2);
    aux_time_mut = (aux_time_mut >> 9).wrapping_mul(125).wrapping_add(((aux_time_mut & 0x1ff).wrapping_mul(125)) >> 9);
    aux_time = aux_time_mut;
    aux_time
}

/* Process the data samples of a single queue. The first parameter is a
 * pointer to the queue, the second parameter is the time stamp. This
 * is the time stamp:
 * - of the event that triggered this processing.
 * - or the time stamp when the last processing of this queue stopped.
 *   In this case it stopped at a 4KB page boundary and record the
 *   position on where to continue processing on the next invocation
 *   (see buffer->use_data and buffer->use_size).
 *
 * When this function returns the second parameter is updated to
 * reflect the time stamp of the last processed auxiliary data entry
 * (taken from the trailer entry of that page). The caller uses this
 * returned time stamp to record the last processed entry in this
 * queue.
 *
 * The function returns:
 * 0:  Processing successful. The second parameter returns the
 *     time stamp from the trailer entry until which position
 *     processing took place. Subsequent calls resume from this
 *     position.
 * <0: An error occurred during processing. The second parameter
 *     returns the maximum time stamp.
 * >0: Done on this queue. The second parameter returns the
 *     maximum time stamp.
 */
unsafe extern "C" fn s390_cpumsf_samples(sfq: *mut s390_cpumsf_queue, ts: *mut u64) -> c_int {
    let sf = (*sfq).sf;
    let buf = (*(*sfq).buffer).use_data;
    let len = (*(*sfq).buffer).use_size;
    let mut bsdes: u16 = 0;
    let mut dsdes: u16 = 0;
    let mut pos: size_t = 0;
    let mut err: c_int = 1;
    let mut aux_ts: u64;

    if !s390_cpumsf_validate((*sf).machine_type as c_int, buf, len, &mut bsdes, &mut dsdes) {
        *ts = !0u64;
        return -1;
    }

    aux_ts = get_trailer_time(buf);
    if aux_ts == 0 {
        pr_err(b"[%#08llx] Invalid AUX trailer entry TOD clock base\n\0".as_ptr() as *const c_char, (*(*sfq).buffer).data_offset as s64);
        aux_ts = !0u64;
        goto_out(sfq, ts, aux_ts);
        return err;
    }
    if aux_ts > *ts {
        *ts = aux_ts;
        return 0;
    }

    while pos < len {
        let basic = buf.add(pos) as *mut hws_basic_entry;
        if s390_cpumsf_make_event(pos, basic, sfq) {
            pos += bsdes as usize;
        } else {
            err = -EBADF;
            goto_out(sfq, ts, aux_ts);
            return err;
        }

        pos += dsdes as usize;

        if !s390_cpumsf_reached_trailer(bsdes as usize + dsdes as usize, pos) {
            pos = (pos + S390_CPUMSF_PAGESZ) & !(S390_CPUMSF_PAGESZ - 1);
            if pos >= len {
                break;
            }
            aux_ts = get_trailer_time(buf.add(pos));
            if aux_ts == 0 {
                aux_ts = !0u64;
                goto_out(sfq, ts, aux_ts);
                return err;
            }
            if aux_ts > *ts {
                *ts = aux_ts;
                (*(*sfq).buffer).use_data = (*(*sfq).buffer).use_data.add(pos);
                (*(*sfq).buffer).use_size -= pos;
                return 0;
            }
        }
    }
    goto_out(sfq, ts, aux_ts);
    err
}

unsafe fn goto_out(sfq: *mut s390_cpumsf_queue, ts: *mut u64, aux_ts: u64) {
    *ts = aux_ts;
    (*(*sfq).buffer).use_size = 0;
    (*(*sfq).buffer).use_data = null_mut();
}

/* Run the s390 auxiliary trace decoder.
 * Select the queue buffer to operate on, the caller already selected
 * the proper queue, depending on second parameter 'ts'.
 * This is the time stamp until which the auxiliary entries should
 * be processed. This value is updated by called functions and
 * returned to the caller.
 *
 * Resume processing in the current buffer. If there is no buffer
 * get a new buffer from the queue and setup start position for
 * processing.
 * When a buffer is completely processed remove it from the queue
 * before returning.
 *
 * This function returns
 * 1: When the queue is empty. Second parameter will be set to
 *    maximum time stamp.
 * 0: Normal processing done.
 * <0: Error during queue buffer setup. This causes the caller
 *     to stop processing completely.
 */
unsafe extern "C" fn s390_cpumsf_run_decoder(sfq: *mut s390_cpumsf_queue, ts: *mut u64) -> c_int {
    let mut buffer: *mut auxtrace_buffer;
    let queue = (*(*sfq).sf).queues.queue_array.add((*sfq).queue_nr as usize);
    let mut err: c_int;

    if (*sfq).buffer.is_null() {
        buffer = auxtrace_buffer__next(queue, (*sfq).buffer);
        (*sfq).buffer = buffer;
        if buffer.is_null() {
            *ts = !0u64;
            return 1;
        }
        if !(*buffer).data.is_null() {
            (*buffer).use_size = (*buffer).size;
            (*buffer).use_data = (*buffer).data as *mut u8;
        }
        if !(*sfq).logfile.is_null() {
            let rc = fwrite((*buffer).data, (*buffer).size, 1, (*sfq).logfile);
            if rc != 1 {
                pr_err(b"Failed to write auxiliary data\n\0".as_ptr() as *const c_char);
            }
        }
    } else {
        buffer = (*sfq).buffer;
    }

    if (*buffer).data.is_null() {
        let fd = perf_data__fd((*(*(*sfq).sf).session).data);

        (*buffer).data = auxtrace_buffer__get_data(buffer, fd);
        if (*buffer).data.is_null() {
            return -ENOMEM;
        }
        (*buffer).use_size = (*buffer).size;
        (*buffer).use_data = (*buffer).data as *mut u8;

        if !(*sfq).logfile.is_null() {
            let rc = fwrite((*buffer).data, (*buffer).size, 1, (*sfq).logfile);
            if rc != 1 {
                pr_err(b"Failed to write auxiliary data\n\0".as_ptr() as *const c_char);
            }
        }
    }
    pr_debug4(b"%s queue_nr:%d buffer:%lld offset:%#llx size:%#zx rest:%#zx\n\0".as_ptr() as *const c_char,
              b"s390_cpumsf_run_decoder\0".as_ptr() as *const c_char, (*sfq).queue_nr, (*buffer).buffer_nr,
              (*buffer).offset, (*buffer).size, (*buffer).use_size);
    err = s390_cpumsf_samples(sfq, ts);

    if err != 0 {
        (*sfq).buffer = null_mut();
        list_del_init(&mut (*buffer).list);
        auxtrace_buffer__free(buffer);
        if err > 0 {
            err = 0;
        }
    }
    err
}

unsafe extern "C" fn s390_cpumsf_alloc_queue(sf: *mut s390_cpumsf, queue_nr: c_uint) -> *mut s390_cpumsf_queue {
    let sfq = zalloc(size_of::<s390_cpumsf_queue>()) as *mut s390_cpumsf_queue;

    if sfq.is_null() {
        return null_mut();
    }

    (*sfq).sf = sf;
    (*sfq).queue_nr = queue_nr;
    (*sfq).cpu = -1;
    if (*sf).use_logfile {
        let mut name: *mut c_char = null_mut();
        let rc: c_int;

        rc = if !(*sf).logdir.is_null() {
            asprintf(&mut name, b"%s/aux.smp.%02x\0".as_ptr() as *const c_char, (*sf).logdir, queue_nr)
        } else {
            asprintf(&mut name, b"aux.smp.%02x\0".as_ptr() as *const c_char, queue_nr)
        };
        if rc > 0 {
            (*sfq).logfile = fopen(name, b"w\0".as_ptr() as *const c_char);
        }
        if (*sfq).logfile.is_null() {
            pr_err(b"Failed to open auxiliary log file %s,continue...\n\0".as_ptr() as *const c_char, name);
            (*sf).use_logfile = false;
        }
        free(name as *mut c_void);
    }
    sfq
}

unsafe extern "C" fn s390_cpumsf_setup_queue(sf: *mut s390_cpumsf, queue: *mut auxtrace_queue, queue_nr: c_uint, ts: u64) -> c_int {
    let mut sfq = (*queue).priv_ as *mut s390_cpumsf_queue;

    if list_empty(&mut (*queue).head) {
        return 0;
    }

    if sfq.is_null() {
        sfq = s390_cpumsf_alloc_queue(sf, queue_nr);
        if sfq.is_null() {
            return -ENOMEM;
        }
        (*queue).priv_ = sfq as *mut c_void;

        if (*queue).cpu != -1 {
            (*sfq).cpu = (*queue).cpu;
        }
    }
    auxtrace_heap__add(&mut (*sf).heap, queue_nr, ts)
}

unsafe extern "C" fn s390_cpumsf_setup_queues(sf: *mut s390_cpumsf, ts: u64) -> c_int {
    let mut i: c_uint = 0;
    let mut ret: c_int = 0;

    while i < (*sf).queues.nr_queues {
        ret = s390_cpumsf_setup_queue(sf, (*sf).queues.queue_array.add(i as usize), i, ts);
        if ret != 0 {
            break;
        }
        i += 1;
    }
    ret
}

unsafe extern "C" fn s390_cpumsf_update_queues(sf: *mut s390_cpumsf, ts: u64) -> c_int {
    if !(*sf).queues.new_data {
        return 0;
    }

    (*sf).queues.new_data = false;
    s390_cpumsf_setup_queues(sf, ts)
}

unsafe extern "C" fn s390_cpumsf_process_queues(sf: *mut s390_cpumsf, timestamp: u64) -> c_int {
    let mut queue_nr: c_uint;
    let mut ts: u64;
    let mut ret: c_int;

    loop {
        if (*sf).heap.heap_cnt == 0 {
            return 0;
        }

        if (*(*sf).heap.heap_array).ordinal >= timestamp {
            return 0;
        }

        queue_nr = (*(*sf).heap.heap_array).queue_nr;
        let queue = (*sf).queues.queue_array.add(queue_nr as usize);
        let sfq = (*queue).priv_ as *mut s390_cpumsf_queue;

        auxtrace_heap__pop(&mut (*sf).heap);
        if (*sf).heap.heap_cnt != 0 {
            ts = (*(*sf).heap.heap_array).ordinal + 1;
            if ts > timestamp {
                ts = timestamp;
            }
        } else {
            ts = timestamp;
        }

        ret = s390_cpumsf_run_decoder(sfq, &mut ts);
        if ret < 0 {
            auxtrace_heap__add(&mut (*sf).heap, queue_nr, ts);
            return ret;
        }
        if ret == 0 {
            ret = auxtrace_heap__add(&mut (*sf).heap, queue_nr, ts);
            if ret < 0 {
                return ret;
            }
        }
    }
}

unsafe extern "C" fn s390_cpumsf_synth_error(sf: *mut s390_cpumsf, code: c_int, cpu: c_int, pid: pid_t, tid: pid_t, ip: u64, timestamp: u64) -> c_int {
    let mut msg = vec![0 as c_char; MAX_AUXTRACE_ERROR_MSG];
    let mut event: perf_event = zeroed();
    let err: c_int;

    strncpy(msg.as_mut_ptr(), b"Lost Auxiliary Trace Buffer\0".as_ptr() as *const c_char, msg.len() - 1);
    auxtrace_synth_error(&mut event.auxtrace_error, PERF_AUXTRACE_ERROR_ITRACE, code, cpu, pid, tid, ip, msg.as_mut_ptr(), timestamp);

    err = perf_session__deliver_synth_event((*sf).session, &mut event, null_mut());
    if err != 0 {
        pr_err(b"s390 Auxiliary Trace: failed to deliver error event,error %d\n\0".as_ptr() as *const c_char, err);
    }
    err
}

unsafe extern "C" fn s390_cpumsf_lost(sf: *mut s390_cpumsf, sample: *mut perf_sample) -> c_int {
    s390_cpumsf_synth_error(sf, 1, (*sample).cpu, (*sample).pid, (*sample).tid, 0, (*sample).time)
}

unsafe extern "C" fn s390_cpumsf_process_event(session: *mut perf_session, event: *mut perf_event, sample: *mut perf_sample, tool: *const perf_tool) -> c_int {
    /* container_of(session->auxtrace, struct s390_cpumsf, auxtrace) */
    let sf = (*session).auxtrace as *mut s390_cpumsf;
    let timestamp = (*sample).time;
    let mut err: c_int = 0;

    if dump_trace {
        return 0;
    }

    if !(*tool).ordered_events {
        pr_err(b"s390 Auxiliary Trace requires ordered events\n\0".as_ptr() as *const c_char);
        return -EINVAL;
    }

    if (*event).header.type_ == PERF_RECORD_SAMPLE && (*sample).raw_size != 0 {
        let ev_bc000 = evlist__event2evsel((*session).evlist, event);
        if !ev_bc000.is_null() && (*ev_bc000).core.attr.config == PERF_EVENT_CPUM_CF_DIAG {
            err = s390_cpumcf_dumpctr(sf, sample);
        }
        return err;
    }

    if (*event).header.type_ == PERF_RECORD_AUX && ((*event).aux.flags & PERF_AUX_FLAG_TRUNCATED) != 0 {
        return s390_cpumsf_lost(sf, sample);
    }

    if timestamp != 0 {
        err = s390_cpumsf_update_queues(sf, timestamp);
        if err == 0 {
            err = s390_cpumsf_process_queues(sf, timestamp);
        }
    }
    err
}

unsafe extern "C" fn s390_cpumsf_process_auxtrace_event(session: *mut perf_session, event: *mut perf_event, _tool: *const perf_tool) -> c_int {
    /* container_of(session->auxtrace, struct s390_cpumsf, auxtrace) */
    let sf = (*session).auxtrace as *mut s390_cpumsf;
    let fd = perf_data__fd((*session).data);
    let mut buffer: *mut auxtrace_buffer = null_mut();
    let data_offset: off_t;
    let err: c_int;

    if (*sf).data_queued {
        return 0;
    }

    if perf_data__is_pipe((*session).data) {
        data_offset = 0;
    } else {
        data_offset = lseek(fd, 0, SEEK_CUR);
        if data_offset == -1 {
            return -errno;
        }
    }

    err = auxtrace_queues__add_event(&mut (*sf).queues, session, event, data_offset, &mut buffer);
    if err != 0 {
        return err;
    }

    /* Dump here after copying piped trace out of the pipe */
    if dump_trace {
        if !auxtrace_buffer__get_data(buffer, fd).is_null() {
            s390_cpumsf_dump_event(sf, (*buffer).data as *mut u8, (*buffer).size);
            auxtrace_buffer__put_data(buffer);
        }
    }
    0
}

unsafe extern "C" fn s390_cpumsf_free_events(_session: *mut perf_session) {}

unsafe extern "C" fn s390_cpumsf_flush(_session: *mut perf_session, _tool: *const perf_tool) -> c_int {
    0
}

unsafe extern "C" fn s390_cpumsf_free_queues(session: *mut perf_session) {
    /* container_of(session->auxtrace, struct s390_cpumsf, auxtrace) */
    let sf = (*session).auxtrace as *mut s390_cpumsf;
    let queues = &mut (*sf).queues as *mut auxtrace_queues;
    let mut i: c_uint = 0;

    while i < (*queues).nr_queues {
        let q = (*queues).queue_array.add(i as usize);
        let sfq = (*q).priv_ as *mut s390_cpumsf_queue;

        if !sfq.is_null() {
            if !(*sfq).logfile.is_null() {
                fclose((*sfq).logfile);
                (*sfq).logfile = null_mut();
            }
            if !(*sfq).logfile_ctr.is_null() {
                fclose((*sfq).logfile_ctr);
                (*sfq).logfile_ctr = null_mut();
            }
        }
        zfree(&mut (*q).priv_);
        i += 1;
    }
    auxtrace_queues__free(queues);
}

unsafe extern "C" fn s390_cpumsf_free(session: *mut perf_session) {
    /* container_of(session->auxtrace, struct s390_cpumsf, auxtrace) */
    let sf = (*session).auxtrace as *mut s390_cpumsf;

    auxtrace_heap__free(&mut (*sf).heap);
    s390_cpumsf_free_queues(session);
    (*session).auxtrace = null_mut();
    zfree(&mut (*sf).logdir as *mut *mut c_char as *mut *mut c_void);
    free(sf as *mut c_void);
}

unsafe extern "C" fn s390_cpumsf_evsel_is_auxtrace(_session: *mut perf_session, evsel: *mut evsel) -> bool {
    (*evsel).core.attr.type_ == PERF_TYPE_RAW && (*evsel).core.attr.config == PERF_EVENT_CPUM_SF_DIAG
}

unsafe extern "C" fn s390_cpumsf_get_type(cpuid: *const c_char) -> c_int {
    let mut family: c_uint = 0;
    let ret = sscanf(cpuid, b"%*[^,],%u\0".as_ptr() as *const c_char, &mut family);
    if ret == 1 { family as c_int } else { 0 }
}

/* Check itrace options set on perf report command.
 * Return true, if none are set or all options specified can be
 * handled on s390 (currently only option 'd' for logging.
 * Return false otherwise.
 */
unsafe extern "C" fn check_auxtrace_itrace(itops: *mut itrace_synth_opts) -> bool {
    let mut ison = false;

    if itops.is_null() || !(*itops).set {
        return true;
    }
    ison = (*itops).inject || (*itops).instructions || (*itops).branches ||
        (*itops).transactions || (*itops).ptwrites ||
        (*itops).pwr_events || (*itops).errors ||
        (*itops).dont_decode || (*itops).calls || (*itops).returns ||
        (*itops).callchain || (*itops).thread_stack ||
        (*itops).last_branch || (*itops).add_callchain ||
        (*itops).add_last_branch;
    if !ison {
        return true;
    }
    pr_err(b"Unsupported --itrace options specified\n\0".as_ptr() as *const c_char);
    false
}

/* Check for AUXTRACE dump directory if it is needed.
 * On failure print an error message but continue.
 * Return 0 on wrong keyword in config file and 1 otherwise.
 */
unsafe extern "C" fn s390_cpumsf__config(var: *const c_char, value: *const c_char, cb: *mut c_void) -> c_int {
    let sf = cb as *mut s390_cpumsf;
    let mut stbuf: stat = zeroed();
    let rc: c_int;

    if strcmp(var, b"auxtrace.dumpdir\0".as_ptr() as *const c_char) != 0 {
        return 0;
    }
    (*sf).logdir = strdup(value);
    if (*sf).logdir.is_null() {
        pr_err(b"Failed to find auxtrace log directory %s, continue with current directory...\n\0".as_ptr() as *const c_char, value);
        return 1;
    }
    rc = stat((*sf).logdir, &mut stbuf);
    if rc == -1 || !S_ISDIR(stbuf.st_mode) {
        pr_err(b"Missing auxtrace log directory %s, continue with current directory...\n\0".as_ptr() as *const c_char, value);
        zfree(&mut (*sf).logdir as *mut *mut c_char as *mut *mut c_void);
    }
    1
}

#[no_mangle]
pub unsafe extern "C" fn s390_cpumsf_process_auxtrace_info(event: *mut perf_event, session: *mut perf_session) -> c_int {
    let auxtrace_info = &mut (*event).auxtrace_info as *mut perf_record_auxtrace_info;
    let sf: *mut s390_cpumsf;
    let mut err: c_int;

    if (*auxtrace_info).header.size as usize  < size_of::<perf_record_auxtrace_info>() {
        return -EINVAL;
    }

    sf = zalloc(size_of::<s390_cpumsf>()) as *mut s390_cpumsf;
    if sf.is_null() {
        return -ENOMEM;
    }

    if !check_auxtrace_itrace((*session).itrace_synth_opts) {
        err = -EINVAL;
        zfree(&mut (*sf).logdir as *mut *mut c_char as *mut *mut c_void);
        free(sf as *mut c_void);
        return err;
    }
    (*sf).use_logfile = (*(*session).itrace_synth_opts).log;
    if (*sf).use_logfile {
        perf_config(s390_cpumsf__config, sf as *mut c_void);
    }

    err = auxtrace_queues__init(&mut (*sf).queues);
    if err != 0 {
        zfree(&mut (*sf).logdir as *mut *mut c_char as *mut *mut c_void);
        free(sf as *mut c_void);
        return err;
    }

    (*sf).session = session;
    (*sf).machine = &mut (*session).machines.host;
    (*sf).auxtrace_type = (*auxtrace_info).type_;
    (*sf).pmu_type = PERF_TYPE_RAW;
    (*sf).machine_type = s390_cpumsf_get_type((*perf_session__env(session)).cpuid) as u16;

    (*sf).auxtrace.process_event = Some(s390_cpumsf_process_event);
    (*sf).auxtrace.process_auxtrace_event = Some(s390_cpumsf_process_auxtrace_event);
    (*sf).auxtrace.flush_events = Some(s390_cpumsf_flush);
    (*sf).auxtrace.free_events = Some(s390_cpumsf_free_events);
    (*sf).auxtrace.free = Some(s390_cpumsf_free);
    (*sf).auxtrace.evsel_is_auxtrace = Some(s390_cpumsf_evsel_is_auxtrace);
    (*session).auxtrace = &mut (*sf).auxtrace;

    if dump_trace {
        return 0;
    }

    err = auxtrace_queues__process_index(&mut (*sf).queues, session);
    if err != 0 {
        auxtrace_queues__free(&mut (*sf).queues);
        (*session).auxtrace = null_mut();
        zfree(&mut (*sf).logdir as *mut *mut c_char as *mut *mut c_void);
        free(sf as *mut c_void);
        return err;
    }

    if (*sf).queues.populated {
        (*sf).data_queued = true;
    }

    0
}
